if (n == 0) {
    return dcomp(1.0, 0.0);
}

// Threshold for switching to Stirling approximation to prevent overflow of n!
// 170! is roughly the limit for double precision (approx 1.8e308)
if (n < 150) {
    dcomp result = std::pow(alpha, n);
    double fact = 1.0;
    for (unsigned long i = 1; i <= n; ++i) {
        fact *= i;
    }
    return result / std::sqrt(fact);
} else {
    // Stirling's approximation: n! ≈ sqrt(2 * pi * n) * (n / e)^n
    // Coefficient = alpha^n / sqrt(n!)
    // |coeff| = |alpha|^n / ( (2 * pi * n)^0.25 * (n / e)^(n/2) )
    // |coeff| = (|alpha| * sqrt(e / n))^n / (2 * pi * n)^0.25

    double abs_alpha = std::abs(alpha);
    double phase = std::arg(alpha);

    double log_coeff_mag = n * std::log(abs_alpha * std::sqrt(std::exp(1.0) / n)) 
                           - 0.25 * std::log(2.0 * std::acos(-1.0) * n);

    double magnitude = std::exp(log_coeff_mag);
    double total_phase = n * phase;

    return std::polar(magnitude, total_phase);
}
// END_CODE

